 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # The 8s form full-width/full-height compartment boundaries.
    row_blocks = []
    start = 0
    for r in range(h):
        if all(v == 8 for v in grid[r]):
            if start < r:
                row_blocks.append(list(range(start, r)))
            start = r + 1
    if start < h:
        row_blocks.append(list(range(start, h)))
    col_blocks = []
    start = 0
    for c in range(w):
        if all(grid[r][c] == 8 for r in range(h)):
            if start < c:
                col_blocks.append(list(range(start, c)))
            start = c + 1
    if start < w:
        col_blocks.append(list(range(start, w)))

    # Work at compartment granularity. Same-color markers aligned in a row
    # or column draw a segment between them; crossings become color 6.
    nr, nc = len(row_blocks), len(col_blocks)
    marks = {}
    for br, rows in enumerate(row_blocks):
        for bc, cols in enumerate(col_blocks):
            for r in rows:
                for c in cols:
                    v = grid[r][c]
                    if v not in (0, 8):
                        marks.setdefault(v, set()).add((br, bc))
    painted = {}
    for color, pts in marks.items():
        pts = sorted(pts)
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                if r1 == r2:
                    for c in range(min(c1, c2), max(c1, c2) + 1):
                        painted[(r1, c)] = painted.get((r1, c), set()) | {color}
                elif c1 == c2:
                    for r in range(min(r1, r2), max(r1, r2) + 1):
                        painted[(r, c1)] = painted.get((r, c1), set()) | {color}
    out = [row[:] for row in grid]
    for (br, bc), colors in painted.items():
        fill = 6 if 2 in colors and 3 in colors else min(colors)
        for r in row_blocks[br]:
            for c in col_blocks[bc]:
                out[r][c] = fill
    return out
